var TldrThis, ListSelection, displayError;

TldrThis = function() {
  return {
    launch: function() {
      this.trial =
        typeof window.api_key === "undefined" || window.api_key === "";
      this.domain = window.domain;
      let that = this;
      chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {
        that.article = tabs[0].url;
        $.getJSON("https://api.ipify.org/?format=json", function(e) {
          window.ip_address = e.ip;
          return that.fetch();
        });
      });
    },
    fetch: function() {
      var _this;
      _this = this;
      _this.cleanTldrResults();
      return $.ajax({
        url:
          "https://v1.tldrthis.com/tldr/process-text-api/?ip_address=" +
          window.ip_address,
        type: "POST",
        data: JSON.stringify({
          text: _this.article,
          api_key: window.api_key,
          summarizer_type: window.summarizer_type,
          display_keywords: window.display_keywords
        }),
        contentType: "application/json;charset=UTF-8",
        dataType: "json",
        error: function(xhr) {
          $(".summary-placeholder").hide();
          if (xhr.status === 400) {
            return displayError("Sorry, something went wrong on the query.");
          } else if (xhr.status === 401) {
            return $(".connect-again-container").show();
          } else if (xhr.status === 403) {
            $("#tldr-this-page").hide();
            return $("#blocked-notification").show();
          } else if (xhr.status === 429) {
            if (!_this.trial) {
              return $(".upgrade-container").show();
            }

            return $(".connect-container").show();
          } else if (xhr.status === 500) {
            return displayError(
              "Sorry, we couldn't generate a summary for the requested URL."
            );
          } else {
            $("#tldr-this-page").hide();
            return $("#blocked-notification").show();
          }
        },
        success: function(data) {
          // summary
          var summary_array = JSON.parse(data[1]);
          var summary = "";
          if (summary_array.length === 0) {
            $(".no-result-container .domain").text(_this.domain);
            $(".no-result-container").show();
            $(".summary-placeholder").hide();
            return;
          } else {
            jQuery.each(summary_array, function(key, value) {
              summary += `<li>` + value + `</li>`;
            });
          }
          _this.summary = summary;

          if (data[0]) {
            _this.title = data[0];
          } else {
            _this.title = "SUMMARY";
          }

          _this.article_authors = data[3];
          _this.article_publish_date = data[4];
          _this.saved_time = data[5];
          _this.keywords = data[6];
          $(".summary-placeholder").hide();
          return _this.render();
        }
      });
    },
    render: function() {
      $("#summary").html("");
      $("#summary").append(this.summary);
      $("#title").text(this.title);

      $("#article_metadata").empty();
      if (this.article_authors || this.article_publish_date) {
        if (this.article_authors && !this.article_publish_date) {
          $("#article_metadata").append(
            `<i class="fas fa-pen"></i> <span>&nbsp; ` +
              this.article_authors +
              `</span> &nbsp;|&nbsp; <i class="fas fa-hourglass-end"></i>
                      <span>&nbsp; Time Saved: ` +
              this.saved_time +
              ` mins</span>`
          );
        } else if (!this.article_authors && this.article_publish_date) {
          $("#article_metadata").append(
            `<i class="far fa-calendar"></i> <span>&nbsp; ` +
              this.article_publish_date +
              `</span> &nbsp;|&nbsp; <i class="fas fa-hourglass-end"></i>
                      <span>&nbsp; Time Saved: ` +
              this.saved_time +
              ` mins</span>`
          );
        } else {
          $("#article_metadata").append(
            `<i class="fas fa-pen"></i
                > <span>&nbsp; ` +
              this.article_authors +
              `</span>
                    &nbsp;|&nbsp;
                <i class="far fa-calendar"></i
                > <span>&nbsp; ` +
              this.article_publish_date +
              `</span> &nbsp;|&nbsp; <i class="fas fa-hourglass-end"></i>
                      <span>&nbsp; Time Saved: ` +
              this.saved_time +
              ` mins</span>`
          );
        }
      }

      if (this.keywords) {
        entities_array = this.keywords;
        var entities = "";
        $("#keywords-container").html("");
        if (entities_array.length !== 0) {
          jQuery.each(entities_array, function(key, value) {
            entities +=
              `<div class="btn-white btn-sm mt-1" style="display: inline-block; margin-right: 4px; text-transform: capitalize;">
                <a href="http://www.google.com/search?q=` +
              value +
              `" target="_blank" rel="nofollow">` +
              value +
              `</a></div>`;
          });
        }
        $("#keywords-container").append(entities);
      }
      if (this.trial) {
        $("#signup-cta").show();
        $("#header").css("text-align", "left");
      }
      $(".article-metadata-container").show();
      this.loadAccountInformation();
      countCall();
      this.feedbackNotification();
      $("body").css({
        height: "auto"
      });
    },
    cleanTldrResults: function() {
      $(".summary-placeholder").show();
      $(".article-metadata-container").hide();
      return;
    },
    loadAccountInformation: function() {
      return Account.get(function(json) {
        if (json === "none") {
          $(".account-loading").hide();
          return $(".account-not-logged").show();
        } else {
          $(".account-loading").hide();
          $(".account-calls-available").text(
            Utilities.numberWithCommas(json.coins)
          );
          return $(".account-logged").show();
        }
      });
    },
    feedbackNotification: function() {
      chrome.storage.sync.get("calls_count", function(value) {
        if (value["calls_count"] >= 20) {
          return chrome.storage.sync.get("has_given_feedback", function(value) {
            if (typeof value["has_given_feedback"] === "undefined") {
              return $(".feedback-notification").slideDown(300);
            }
          });
        }
      });
      $("#open-rate-notification").click(function() {
        $(".feedback-notification").slideUp(300);
        return $(".rate-notification").slideDown(300);
      });
      $("#open-contact-notification").click(function() {
        $(".feedback-notification").slideUp(300);
        return $(".contact-notification").slideDown(300);
      });
      return $(".feedback_link").click(function() {
        return chrome.storage.sync.set({
          has_given_feedback: true
        });
      });
    }
  };
};

ListSelection = {
  appendSelector: function() {
    var selected_list_id;
    $(".list_select_container").html('<select class="list_select"></select>');
    if (window.summarizer_type) {
      selected_list_id = window.summarizer_type;
    } else {
      selected_list_id = "free";
    }
    [
      { id: "free", name: "Basic Summarizer" },
      { id: "premium", name: "Advanced Summarizer" }
    ].forEach(function(val, i) {
      var selected;
      if (selected_list_id === val.id) {
        selected = 'selected="selected"';
      } else {
        selected = "";
      }
      return $(".list_select").append(
        "<option " +
          selected +
          ' value="' +
          val.id +
          '">' +
          val.name +
          "</option>"
      );
    });
    return this.updateCurrent();
  },
  updateCurrent: function() {
    return $(".list_select").on("change", function() {
      chrome.storage.sync.set({
        summarizer_type: $(this).val()
      });
      window.summarizer_type = $(this).val();
      tldrThis = new TldrThis();
      tldrThis.launch();
      tldrThis.loadAccountInformation();
    });
  }
};

displayError = function(html) {
  $(".error-message").html(html);
  $("html, body").animate(
    {
      scrollTop: 0
    },
    300
  );
  $(".error-container")
    .delay(300)
    .slideDown();
  return setTimeout(function() {
    $(".error-container").slideUp();
  }, 8000);
};

chrome.tabs.query(
  {
    active: true,
    currentWindow: true
  },
  function(tabs) {
    return Account.getApiKey(function(api_key) {
      var tldrThis, withoutSubDomain;
      window.api_key = api_key;
      window.domain = new URL(tabs[0].url).hostname.replace("www.", "");
      // window.display_keywords = false;
      // chrome.storage.sync.set({
      //   display_keywords: false
      // });
      withoutSubDomain = Utilities.withoutSubDomain(window.domain);
      if (withoutSubDomain) {
        window.domain = withoutSubDomain;
      }
      if (window.domain === "" || window.domain.indexOf(".") === -1) {
        return $("#empty-notification").show();
      } else {
        $("#tldr-this-page").show();
        tldrThis = new TldrThis();
        tldrThis.launch();
        tldrThis.loadAccountInformation();

        chrome.storage.sync.get("display_keywords", function(value) {
          $("#display_keywords").prop("checked", value.display_keywords);
          window.display_keywords = value.display_keywords;
        });

        $("#display_keywords").on("change", function() {
          chrome.storage.sync.set({
            display_keywords: this.checked
          });
          window.display_keywords = this.checked;
          tldrThis.launch();
          tldrThis.loadAccountInformation();
        });
        return chrome.storage.sync.get("summarizer_type", function(value) {
          window.summarizer_type = value.summarizer_type;
          return ListSelection.appendSelector();
        });
      }
    });
  }
);
